<?php
require_once __DIR__ . '/../includes/init.php';requireLogin();$pdo=db();$stats=[['Total items',(int)$pdo->query('SELECT COUNT(*) FROM items')->fetchColumn(),'▤','green'],['Total stock',(int)$pdo->query('SELECT COALESCE(SUM(quantity),0) FROM items')->fetchColumn(),'▦','blue'],['Low stock items',(int)$pdo->query('SELECT COUNT(*) FROM items WHERE quantity<=reorder_level')->fetchColumn(),'⚑','amber']];$recent=historyRows([],10);$title='Dashboard';$active='dashboard';layoutStart($title,$active);
?><div class="page-heading"><div><div class="eyebrow">WAREHOUSE OVERVIEW</div><h1>Welcome, <?= e(explode(' ',currentUser()['full_name'])[0]) ?></h1><p>Here’s a quick look at current inventory and recent activity.</p></div><a class="button light" href="<?= e(url('user/items.php')) ?>">Browse inventory →</a></div><section class="stats-grid three"><?php foreach($stats as [$label,$value,$icon,$color]):?><article class="stat-card"><span class="stat-icon <?= e($color) ?>"><?= e($icon) ?></span><span class="stat-label"><?= e($label) ?></span><strong><?= number_format($value) ?></strong><span class="stat-note">Live inventory data</span></article><?php endforeach;?></section><section class="panel"><div class="panel-heading"><div><h2>Recent stock history</h2><p>Latest 10 stock movements</p></div><a class="text-link" href="<?= e(url('user/items.php')) ?>">View items →</a></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Item</th><th>Type</th><th>Qty</th><th>Reference</th></tr></thead><tbody><?php if(!$recent):?><tr><td colspan="5" class="empty">No stock history available.</td></tr><?php else:foreach($recent as $r):?><tr><td><?= e(dateValue($r['movement_date'])) ?></td><td><b><?= e($r['item_name']) ?></b><small class="subtext"><?= e($r['item_code']) ?></small></td><td><span class="badge <?= strtolower($r['movement_type']) ?>-badge"><?= e($r['movement_type']) ?></span></td><td><?= e($r['quantity'].' '.$r['unit']) ?></td><td><?= e($r['reference_note']?:'—') ?></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php layoutEnd();?>
